"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""
import re

INPUT_PATH = "/app/input.txt"
OUTPUT_PATH = "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}
ROLE_RE = re.compile(r"^[A-Za-z0-9_-]+$")
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace valid {variable} patterns with {var} for matching."""
    return VAR_RE.sub("{var}", path)


def segment_count(path):
    """Count non-empty segments split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def parse_input(text):
    """Split into the three sections separated by empty lines."""
    sections = []
    current = []
    for line in text.split("\n"):
        if line.strip() == "":
            if current:
                sections.append(current)
                current = []
            # multiple blank lines: only keep first three sections anyway
        else:
            current.append(line)
    if current:
        sections.append(current)
    # Pad to three sections
    while len(sections) < 3:
        sections.append([])
    return sections[0], sections[1], sections[2]


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines."""
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, permission = parts
        if path.strip() == "":
            break
        method_u = method.upper()
        if method_u not in VALID_METHODS:
            break
        if not ROLE_RE.match(role):
            break
        perm_u = permission.upper()
        if perm_u not in VALID_PERMISSIONS:
            break
        endpoints.append((path, method_u, role, perm_u))
    return endpoints


def parse_base_exclude(lines):
    base = None
    excludes = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for role in parts[1:]:
                excludes.add(role)
    return base, excludes


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines."""
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if path.strip() == "":
            break
        method_u = method.upper()
        if method_u not in VALID_METHODS:
            break
        plan.append((path, method_u))
    return plan


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    ep_lines, be_lines, plan_lines = parse_input(text)

    endpoints = parse_endpoints(ep_lines)
    base, excludes = parse_base_exclude(be_lines)
    plan = parse_plan(plan_lines)

    # ---- base filter ----
    def base_ok(path):
        if base is None:
            return True
        return path.startswith(base)

    # ---- determine which endpoints are "eligible" (base filter) ----
    # eligible = passes base filter
    # role-eligible = passes base filter and role not excluded

    # ---- Rule 1 + 2: determine included (path, method, role) tuples ----
    # Work with normalized paths for matching.

    # Map: normalized path -> list of endpoints (input order)
    from collections import OrderedDict

    norm_groups = OrderedDict()
    for idx, (path, method, role, perm) in enumerate(endpoints):
        norm_groups.setdefault(normalize_path(path), []).append(
            (idx, path, method, role, perm)
        )

    # All eligible endpoint indices (base filter only)
    eligible = [
        (idx, path, method, role, perm)
        for idx, (path, method, role, perm) in enumerate(endpoints)
        if base_ok(path)
    ]

    # All role-eligible endpoint indices (base + exclude filter)
    role_eligible = [
        (idx, path, method, role, perm)
        for idx, (path, method, role, perm) in endpoints
        if base_ok(path) and role not in excludes
    ]

    # ---- Determine target endpoints (what we inherit parents for) ----
    if plan:
        # Targets: plan endpoints that exist in ENDPOINTS (after cutoff),
        # matched via normalized path.
        targets = []
        seen_target_idx = set()
        for p_path, p_method in plan:
            p_norm = normalize_path(p_path)
            for idx, (path, method, role, perm) in enumerate(endpoints):
                if normalize_path(path) == p_norm and method == p_method:
                    if idx not in seen_target_idx:
                        seen_target_idx.add(idx)
                        targets.append((idx, path, method, role, perm))
    else:
        # Empty PLAN: include all eligible endpoints (role-eligible).
        targets = list(role_eligible)

    # ---- Include set ----
    # Start with role-eligible targets.
    included_idx = set()
    for t in targets:
        included_idx.add(t[0])

    # Parent path resolution:
    # For each target, find parent paths (normalized prefix, different,
    # having at least one eligible endpoint) and include their endpoints.
    # Special case: if a parent path has endpoints only for excluded roles,
    # include them ONLY if they are the only endpoints for that parent path
    # AND the parent path is needed for inheritance.
    target_norms = [normalize_path(t[1]) for t in targets]

    for t_norm in target_norms:
        # find all distinct normalized parent paths
        for parent_norm, members in norm_groups.items():
            if parent_norm == t_norm:
                continue
            if not t_norm.startswith(parent_norm):
                continue
            # parent must have at least one eligible endpoint (base filter)
            has_eligible = any(
                base_ok(m[1]) for m in members
            )
            if not has_eligible:
                continue
            # Determine which of this parent's endpoints to include
            role_el_members = [m for m in members if m[3] not in excludes]
            if role_el_members:
                for m in role_el_members:
                    included_idx.add(m[0])
            else:
                # all members are excluded-role
                # Special case: include ONLY if they are the only
                # endpoints for that parent path (i.e. all members) and
                # the parent path is needed for inheritance (it is, since
                # we found it as a parent of a target).
                for m in members:
                    included_idx.add(m[0])

    # ---- Rule 3: dedupe by (normalized path, method, role), first wins ----
    dedup = OrderedDict()
    for idx, (path, method, role, perm) in enumerate(endpoints):
        if idx not in included_idx:
            continue
        key = (normalize_path(path), method, role)
        if key not in dedup:
            dedup[key] = (path, method, role, perm)

    # ---- Rule 4: ordering ----
    items = list(dedup.values())
    items.sort(key=lambda e: (
        -segment_count(e[0]),
        e[1],          # method alphabetical
        e[2],          # role lexicographic, case-sensitive
        0 if e[3] == "ALLOW" else 1,
    ))

    # ---- Rule 7: uniqueness by original (path, method, role) ----
    seen = set()
    out_lines = []
    for path, method, role, perm in items:
        key = (path, method, role)
        if key in seen:
            continue
        seen.add(key)
        out_lines.append("{} {} {} {}".format(path, method, role, perm))

    if out_lines:
        output = "\n".join(out_lines) + "\n"
    else:
        output = "\n"

    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
