        if perm_u not in VALID_PERMISSIONS:
            break
        endpoints.append((path, method_u, role, perm_u))
    return endpoints


def parse_base_exclude(lines):
    base = None
    excludes = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for role in parts[1:]:
                excludes.add(role)
    return base, excludes


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines."""
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if path.strip() == "":
            break
        method_u = method.upper()
        if method_u not in VALID_METHODS:
            break
        plan.append((path, method_u))
    return plan


