        for t in targets:
            idx, path, method, role, perm = t
            if base_ok(path) and role_ok(role):
                included_idx.add(idx)

        # Parent path resolution for each target
        for t in targets:
            t_norm = normalize_path(t[1])
            for parent_norm, members in norm_groups.items():
                if parent_norm == t_norm:
                    continue
                if not t_norm.startswith(parent_norm):
                    continue
