        # Empty PLAN: all eligible endpoints; excluded roles always
        # filtered out (no inheritance exception applies).
        for idx, (path, method, role, perm) in enumerate(endpoints):
            if base_ok(path) and role_ok(role):
                included_idx.add(idx)

    # ---- Rule 3: dedupe by (normalized path, method, role), first wins ----
    dedup = OrderedDict()
    for idx, (path, method, role, perm) in enumerate(endpoints):
